  if(!editText.trim()){error='Nội dung không được để trống.';return;}
  const fields={expected_version:item.version,content:editText};const signature=JSON.stringify({id:item.id,...fields});
  if(!editCommand||editCommand.signature!==signature)editCommand={signature,requestId:crypto.randomUUID()};
  editBusy=true;error='';
  try{await request(`/api/app/items/${item.id}/content`,{...fields,device_id:device,request_id:editCommand.requestId});editCommand=null;contentEditing=null;notice='Đã lưu nội dung.';await refresh();if(historyItem===item.id)await showHistory(item.id);}
  catch(e){error=`Chưa lưu được: ${message(e)}. Bản đang sửa vẫn ở đây; nếu dữ liệu đã đổi trên máy khác, sao chép bản sửa rồi tải lại.`;}
  finally{editBusy=false;}
 }
 onMount(()=>{
  try{const raw=JSON.parse(localStorage.getItem(queueKey)||'[]');if(!Array.isArray(raw))throw Error('invalid');queue=raw;content=localStorage.getItem(draftKey)||'';kind=localStorage.getItem(kindKey)==='note'?'note':'task';}
  catch{queueBroken=true;error='Không đọc được hàng đợi trên máy; chưa gửi dữ liệu để tránh mất bản nháp.';return;}
  void refresh();if(queue.length)void sync();
  const ticker=window.setInterval(()=>clockNow=Math.floor(Date.now()/1000),1000);
  const retry=()=>{if(queue.length)void sync();else void refresh();},onReminder=()=>void refresh();window.addEventListener('online',retry);window.addEventListener('nhip-reminder-update',onReminder);return()=>{window.clearInterval(ticker);window.removeEventListener('online',retry);window.removeEventListener('nhip-reminder-update',onReminder)};
 });
</script>
<section class="product-workspace" aria-label="Dự án và hộp thư">
 <div class="section-heading"><div><h2>Hộp thư đến</h2><p class="muted">Ghi lại trước, sắp xếp sau. Hỗ trợ AI cho task và ghi chú sẽ có sau.</p></div>{#if queue.length}<span class="muted">{queue.length} chưa đồng bộ</span>{/if}</div>
 {#if error}<div class="error" role="alert"><span>{error}</span>{#if !queueBroken}<button type="button" class="text-action" onclick={refresh}>Làm mới dữ liệu</button>{/if}</div>{/if}
 {#if notice}<p class="notice" role="status">{notice}</p>{/if}
 {#each activeFocus as session(session.id)}<div class="notice focus-session"><div><strong>Đang tập trung: {session.title}</strong><p class="muted">Còn {Math.floor(Math.max(0,session.started_at+session.planned_seconds-clockNow)/60)}:{String(Math.max(0,session.started_at+session.planned_seconds-clockNow)%60).padStart(2,'0')} · Thời gian được ghi vào task này.</p></div><button class="secondary" disabled={actionBusy} onclick={()=>finishFocus(session)}>Kết thúc phiên</button></div>{/each}
 <form class="capture" onsubmit={e=>{e.preventDefault();capture()}}>
  <label for="quick-kind">Loại nội dung</label><select id="quick-kind" bind:value={kind} onchange={()=>localStorage.setItem(kindKey,kind)}><option value="task">Công việc</option><option value="note">Ghi chú</option></select>
  <label for="quick-content">Bạn muốn ghi lại điều gì?</label><textarea id="quick-content" value={content} oninput={e=>draft(e.currentTarget.value)} placeholder="Một việc cần làm hoặc điều cần nhớ…" maxlength="20000"></textarea>
  <div class="section-heading"><small class="muted">Bản nháp lưu trên thiết bị này.</small><button class="primary" disabled={queueBroken}>Lưu vào hộp thư</button></div>
 </form>
 {#if queue.length}<div class="section-heading"><p class="muted">{queue.length} mục đang chờ gửi.</p><button class="text-action" onclick={sync} disabled={syncing}>{syncing?'Đang đồng bộ…':'Thử đồng bộ lại'}</button></div>{/if}
 <div class="section-heading"><h2>Dự án <span class="muted">{projects.length}</span></h2><button class="text-action" onclick={()=>showProject=!showProject}>{showProject?'Đóng':'Dự án mới'}</button></div>
 {#if showProject}<form class="capture" onsubmit={e=>{e.preventDefault();addProject()}}><label for="project-name">Tên dự án</label><input id="project-name" bind:value={name} maxlength="200"/><label for="project-area">Không gian</label><select id="project-area" bind:value={area}><option value="personal">Cá nhân</option><option value="company">Công ty</option></select><label for="project-description">Mô tả (không bắt buộc)</label><textarea id="project-description" bind:value={description}></textarea><div class="form-actions"><button class="primary" disabled={busy}>{busy?'Đang tạo…':'Tạo dự án'}</button></div></form>{/if}
 {#if !projects.length}<p class="empty">Chưa có dự án. Tạo một dự án khi bạn sẵn sàng.</p>{:else}{#each projects as project(project.id)}<div class="task-row"><div class="task-content"><strong>{project.name}</strong><span>{project.area==='personal'?'Cá nhân':'Công ty'} · {project.status==='active'?'Đang hoạt động':project.status==='paused'?'Tạm dừng':project.status==='completed'?'Hoàn thành':'Lưu trữ'} · {project.open_task_count} việc đang mở{project.description?` · ${project.description}`:''}</span></div><button class="text-action" aria-label={'Sửa dự án '+project.name} onclick={()=>startProjectEdit(project)}>Sửa</button><button class="text-action" aria-label={'Xem nội dung dự án '+project.name} onclick={()=>projectFilter=project.id}>Xem nội dung</button></div>
 {#if editingProject===project.id}<form class="capture" onsubmit={e=>{e.preventDefault();saveProject(project)}}><label for={'project-edit-name-'+project.id}>Tên dự án</label><input id={'project-edit-name-'+project.id} bind:value={projectName} maxlength="200"/><label for={'project-edit-description-'+project.id}>Mô tả</label><textarea id={'project-edit-description-'+project.id} bind:value={projectDescription} maxlength="10000"></textarea><label for={'project-edit-status-'+project.id}>Trạng thái</label><select id={'project-edit-status-'+project.id} bind:value={projectStatus}><option value="active">Đang hoạt động</option><option value="paused">Tạm dừng</option><option value="completed">Hoàn thành</option><option value="archived">Lưu trữ</option></select>{#if project.open_task_count&&(projectStatus==='completed'||projectStatus==='archived')}<p class="muted">Còn {project.open_task_count} việc đang mở. Hoàn thành, bỏ hoặc chuyển các việc này trước khi đóng dự án. <button type="button" class="text-action" onclick={()=>projectFilter=project.id}>Xem các việc</button></p>{:else if projectStatus==='paused'&&project.open_task_count}<p class="muted">Tạm dừng dự án giữ nguyên {project.open_task_count} việc đang mở.</p>{/if}<div class="form-actions"><button type="button" class="secondary" onclick={()=>editingProject=null}>Hủy</button><button class="primary" disabled={projectBusy}>{projectBusy?'Đang lưu…':'Lưu dự án'}</button></div></form>{/if}
 {/each}{/if}
 <div class="section-heading product-inbox-heading"><h2>{projectFilter===null?'Nội dung đã lưu':`Dự án: ${projects.find(p=>p.id===projectFilter)?.name||''}`}</h2>{#if projectFilter!==null}<button class="text-action" onclick={()=>projectFilter=null}>Xem tất cả</button>{/if}</div>
 {#if recurringRules.length}<div class="section-heading"><h2>Chuỗi task lặp <span class="muted">{recurringRules.length}</span></h2></div>{#each recurringRules as rule(rule.id)}<div class="task-row"><div class="task-content"><strong>{rule.content}</strong><span>{rule.frequency==='daily'?'Ngày thường':rule.frequency==='weekly'?`Hàng tuần · ${rule.weekdays.map(day=>['T2','T3','T4','T5','T6'][day]).join(', ')}`:`Hàng tháng · ngày ${rule.month_day}`} · {rule.local_time} · {rule.occurrence_count} lần đã sinh · {rule.open_count} chưa xong · {rule.status==='active'?'Đang chạy':rule.status==='paused'?'Tạm dừng':'Đã kết thúc'}</span></div>{#if rule.status!=='ended'}<button class="text-action" disabled={recurrenceBusy} onclick={()=>setRecurrenceStatus(rule,rule.status==='active'?'paused':'active')}>{rule.status==='active'?'Tạm dừng':'Tiếp tục'}</button><button class="text-action" disabled={recurrenceBusy} onclick={()=>setRecurrenceStatus(rule,'ended')}>Kết thúc</button>{/if}</div>{/each}{/if}
 {#if loading}<p class="empty">Đang tải…</p>{:else if !visibleItems.length}<p class="empty">{projectFilter===null?'Hộp thư đang trống.':'Dự án chưa có nội dung.'}</p>{:else}{#each visibleItems as item(item.id)}<div class="task-row" id={'product-item-'+item.id} tabindex="-1"><div class="task-content"><strong class="product-content">{item.content}</strong><span>{item.kind==='task'?'Công việc':'Ghi chú'} · {item.project_id ? projects.find(p=>p.id===item.project_id)?.name||'Dự án' : 'Chưa phân loại'}{item.duration?` · ${item.duration} phút`:''}{item.occurrence_date?` · Lần lặp ${item.occurrence_date}`:''}{item.status==='done'?' · Đã hoàn thành':item.status==='abandoned'?' · Đã bỏ':item.status==='decision'?' · Cần quyết định':item.status==='restructured'?' · Đã tái cấu trúc':''}</span></div>{#if item.status==='inbox'||item.status==='ready'||item.status==='filed'}<button class="text-action" aria-label={'Sửa '+item.content} onclick={()=>startEdit(item)}>Sửa</button><button class="text-action" aria-label={'Phân loại '+item.content} onclick={()=>startClarify(item)}>Phân loại</button>{/if}</div>
 {@const savedPlan=savedPlans.find(p=>p.task_id===item.id)}
 {#if savedPlan}<div class="slots"><h3>Lịch các phiên</h3><p class="muted">Đánh dấu hoàn tất cập nhật trạng thái lịch; thời gian thực tế vẫn được ghi riêng qua Pomodoro.</p>{#each savedPlan.sessions as session(session.id)}<div class="section-heading"><span>{new Date(session.starts_at*1000).toLocaleString('vi-VN',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · {session.duration_minutes} phút</span>{#if session.state==='planned'}<button class="text-action" disabled={sessionBusy!==null} onclick={()=>completePlanSession(savedPlan,session)}>{sessionBusy===session.id?'Đang lưu…':'Đánh dấu hoàn tất'}</button>{:else if session.state==='done'}<span class="muted">Đã hoàn tất</span>{:else}<span class="muted">Đã hủy</span>{/if}</div>{/each}{#if confirmCancelPlan===savedPlan.id}<p class="muted">Hủy sẽ dừng lời nhắc của kế hoạch và gỡ các phiên khỏi lịch. Công việc vẫn được giữ lại.</p><button class="secondary" onclick={()=>confirmCancelPlan=null}>Giữ kế hoạch</button><button class="primary" disabled={cancelingPlan===savedPlan.id} onclick={()=>cancelPlan(item,savedPlan)}>{cancelingPlan===savedPlan.id?'Đang hủy…':'Xác nhận hủy kế hoạch'}</button>{:else}<button class="text-action" onclick={()=>confirmCancelPlan=savedPlan.id}>Hủy kế hoạch</button>{/if}</div>{/if}
 {#if item.kind==='task'}{@const reminder=reminders.find(r=>r.task_id===item.id&&r.state!=='closed')}{@const rule=recurringRules.find(r=>r.template_task_id===item.id)}{#if item.recurrence_rule_id}<p class="muted">Lần lặp trong chuỗi “{recurringRules.find(r=>r.id===item.recurrence_rule_id)?.content||'task lặp'}”.</p>{/if}{#if reminder&&reminder.state==='scheduled'}<p class="muted">Nhắc lúc {new Date(reminder.due_at*1000).toLocaleString('vi-VN')} · Đã hoãn {reminder.snoozes}/3 lần</p>{/if}{#if item.status==='inbox'||item.status==='ready'}<button class="text-action" disabled={actionBusy||activeFocus.length>0} onclick={()=>startTaskFocus(item)}>Tập trung 25 phút</button>{/if}{#if item.status!=='done'&&item.status!=='abandoned'&&item.status!=='decision'&&!item.recurrence_rule_id&&!rule&&!reminder}<button class="text-action" aria-label={'Tạo task lặp từ '+item.content} onclick={()=>startRecurrence(item)}>Tạo chuỗi lặp</button>{/if}{#if item.status!=='done'&&item.status!=='abandoned'&&item.status!=='decision'&&!reminder}<button class="text-action" aria-label={'Tìm và đề xuất lịch cho '+item.content} disabled={slotBusy&&slotTask===item.id} onclick={()=>findSlots(item)}>{slotBusy&&slotTask===item.id?'Đang tìm giờ…':'Tìm lịch trống'}</button>{/if}{#if reminder&&item.status!=='done'&&item.status!=='abandoned'&&item.status!=='decision'}<button class="text-action" aria-label={'Đổi lịch nhắc '+item.content} onclick={()=>startReminder(item)}>Đổi giờ nhắc</button>{/if}
 {#if slotTask===item.id}<div class="slots"><h3>Kế hoạch đề xuất</h3><p class="muted">{slotPlan?.reason||'Đang tính các phiên phù hợp. Chưa có gì được đặt lịch.'}</p>{#if slotPlan?.sessions.length}{#each slotPlan.sessions as session, index (session.starts_at)}<p>{index+1}. {new Date(session.starts_at*1000).toLocaleString('vi-VN',{weekday:'long',day:'numeric',month:'long',hour:'2-digit',minute:'2-digit'})} · {session.duration_minutes} phút</p>{/each}<p class="muted">{slotPlan.complete?'Đủ '+slotPlan.duration_minutes+' phút, chia thành '+slotPlan.sessions.length+' phiên.':`Còn thiếu ${slotPlan.remaining_minutes} phút; thử tăng khoảng ngày hoặc rảnh lịch trước khi áp dụng.`}</p><button class="primary" disabled={!slotPlan.complete||planBusy||!!reminder||!!rule||!!item.recurrence_rule_id} onclick={()=>applyPlan(item)}>{planBusy?'Đang lưu kế hoạch…':'Duyệt và đặt các phiên'}</button>{:else if !slotBusy}<p>Không tìm được khung phù hợp trong 30 ngày tới.</p>{/if}<button class="text-action" onclick={()=>{slotTask=null;slotPlan=null}}>Đóng gợi ý</button></div>{/if}
 {#if recurringForm===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();void createRecurrence(item)}}><label for={'repeat-frequency-'+item.id}>Tần suất</label><select id={'repeat-frequency-'+item.id} bind:value={recurrenceFrequency}><option value="daily">Mỗi ngày trong tuần</option><option value="weekly">Hàng tuần</option><option value="monthly">Hàng tháng</option></select>{#if recurrenceFrequency==='weekly'}<fieldset><legend>Ngày thực hiện (thứ Hai đến thứ Sáu)</legend><div class="form-grid">{#each ['Thứ Hai','Thứ Ba','Thứ Tư','Thứ Năm','Thứ Sáu'] as day,index}<label><input type="checkbox" bind:group={recurrenceWeekdays} value={index}/> {day}</label>{/each}</div></fieldset>{/if}{#if recurrenceFrequency==='monthly'}<label for={'repeat-monthday-'+item.id}>Ngày trong tháng</label><input id={'repeat-monthday-'+item.id} type="number" min="1" max="31" bind:value={recurrenceMonthDay} onchange={e=>{const day=Number(e.currentTarget.value),[year,month]=recurrenceStart.split("-").map(Number),last=new Date(year,month,0).getDate();recurrenceMonthDay=day;recurrenceStart=`${year}-${String(month).padStart(2,"0")}-${String(Math.min(day,last)).padStart(2,"0")}`;}} required/><small class="muted">Nếu tháng đó ngắn hơn, lần lặp dùng ngày cuối tháng.</small>{/if}<label for={'repeat-start-'+item.id}>Ngày thực hiện đầu tiên</label><input id={'repeat-start-'+item.id} type="date" bind:value={recurrenceStart} onchange={e=>{if(recurrenceFrequency==='monthly')recurrenceMonthDay=Number(e.currentTarget.value.slice(-2));}} required/><label for={'repeat-time-'+item.id}>Giờ nhắc</label><input id={'repeat-time-'+item.id} type="time" bind:value={recurrenceTime} required/><p class="muted">Thứ Bảy và Chủ nhật là ngày nghỉ; lịch tháng rơi vào cuối tuần được nhắc vào thứ Hai. Task này là lần lặp đầu tiên; lần sau được tạo riêng và vẫn giữ nếu bị lỡ.</p><div class="form-actions"><button type="button" class="secondary" onclick={()=>recurringForm=null}>Hủy</button><button class="primary" disabled={recurrenceBusy}>{recurrenceBusy?'Đang lưu…':'Bắt đầu lặp'}</button></div></form>{/if}
 {#if reminderForm===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();saveReminder(item)}}><label for={'reminder-time-'+item.id}>Thời điểm nhắc</label><input id={'reminder-time-'+item.id} type="datetime-local" bind:value={reminderTime} required/><label for={'reminder-reason-'+item.id}>Lý do (bắt buộc nếu đã tới hạn)</label><textarea id={'reminder-reason-'+item.id} bind:value={reminderReason} maxlength="2000"></textarea><div class="form-actions"><button type="button" class="secondary" onclick={()=>reminderForm=null}>Hủy</button><button class="primary" disabled={reminderBusy}>{reminderBusy?'Đang lưu…':'Lưu lịch nhắc'}</button></div></form>{/if}{/if}
 {#if contentEditing===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();saveEdit(item)}}><label for={'edit-content-'+item.id}>Nội dung</label><textarea id={'edit-content-'+item.id} bind:value={editText} maxlength="20000"></textarea><div class="form-actions"><button type="button" class="secondary" onclick={()=>contentEditing=null}>Hủy</button><button class="primary" disabled={editBusy}>{editBusy?'Đang lưu…':'Lưu nội dung'}</button></div></form>{/if}
 {#if item.kind==='note'&&item.original_content!==null&&item.original_content!==item.content}<details><summary>Xem ghi chú ban đầu</summary><p class="product-content">{item.original_content}</p></details>{/if}
 <div class="section-heading">{#if item.kind==='task'}{#if item.status==='done'||item.status==='abandoned'}<button class="text-action" disabled={actionBusy} onclick={()=>transition(item,'undo')}>Hoàn tác</button>{:else if item.status==='decision'}<button class="text-action" onclick={()=>{abandoning=item.id;abandonReason=''}}>Bỏ công việc</button>{:else if item.status==='inbox'||item.status==='ready'}<span><button class="text-action" disabled={actionBusy} onclick={()=>transition(item,'complete')}>Hoàn thành</button> · <button class="text-action" onclick={()=>{abandoning=item.id;abandonReason=''}}>Bỏ công việc</button></span>{:else}<span></span>{/if}{:else}<span></span>{/if}<button class="text-action" aria-label={(historyItem===item.id?'Ẩn':'Xem')+' lịch sử '+item.content} onclick={()=>historyItem===item.id?historyItem=null:showHistory(item.id)}>{historyItem===item.id?'Ẩn lịch sử':'Xem lịch sử'}</button></div>
 {#if item.status==='decision'&&item.kind==='task'}<div class="slots"><h3>Cần chọn bước tiếp theo</h3><p>Đã hết ba lượt hoãn. Task sẽ không tiếp tục nhắc cho đến khi bạn chọn một phương án.</p>{#if activeFocus.length}<p class="muted">Một phiên tập trung đang chạy; kết thúc phiên hiện tại trước khi bắt đầu phiên khác.</p>{:else}<button class="primary" disabled={actionBusy} onclick={()=>startFocus(item)}>Làm ngay · 25 phút</button>{/if}<button class="secondary" onclick={()=>startRestructure(item)}>Tái cấu trúc thành task mới</button></div>{/if}
 {#if restructuring===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();void saveRestructure(item)}}><label for={'replacement-content-'+item.id}>Bước hành động mới</label><textarea id={'replacement-content-'+item.id} bind:value={replacementContent} maxlength="20000" required></textarea><label for={'replacement-reason-'+item.id}>Vì sao cần tái cấu trúc?</label><textarea id={'replacement-reason-'+item.id} bind:value={restructureReason} maxlength="2000" required></textarea><label for={'replacement-duration-'+item.id}>Thời lượng dự kiến (phút)</label><input id={'replacement-duration-'+item.id} type="number" min="1" max="1440" bind:value={replacementDuration} required/><label for={'replacement-energy-'+item.id}>Mức tập trung</label><select id={'replacement-energy-'+item.id} bind:value={replacementEnergy}><option value="">Chưa chọn</option><option value="low">Nhẹ</option><option value="medium">Vừa</option><option value="high">Cao</option></select><label for={'replacement-time-'+item.id}>Lịch nhắc cho task mới</label><input id={'replacement-time-'+item.id} type="datetime-local" bind:value={replacementTime} required/><div class="form-actions"><button type="button" class="secondary" onclick={()=>restructuring=null}>Hủy</button><button class="primary" disabled={restructureBusy}>{restructureBusy?'Đang lưu…':'Tạo task thay thế'}</button></div></form>{/if}
 {#if abandoning===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();transition(item,'abandon')}}><label for={'abandon-reason-'+item.id}>Lý do bỏ công việc</label><textarea id={'abandon-reason-'+item.id} bind:value={abandonReason} maxlength="2000"></textarea><div class="form-actions"><button type="button" class="secondary" onclick={()=>abandoning=null}>Hủy</button><button class="primary" disabled={actionBusy}>{actionBusy?'Đang lưu…':'Xác nhận bỏ'}</button></div></form>{/if}
 {#if historyItem===item.id}<div class="slots"><h3>Lịch sử</h3>{#if !historyRows.length}<p>Chưa có thay đổi.</p>{:else}{#each historyRows as row(row.id)}<p>{row.action==='complete'?'Hoàn thành':row.action==='abandon'?'Đã bỏ':row.action==='undo'?'Hoàn tác':row.action==='edit_content'?'Sửa nội dung':row.action==='restructure'?'Tái cấu trúc':'Phân loại'} · {row.created_at}{row.after.reason?` · ${row.after.reason}`:''}{row.after.replacement_task_id?` · Task mới #${row.after.replacement_task_id}`:''}</p>{/each}{/if}</div>{/if}
 {#if editing===item.id}<form class="capture" onsubmit={e=>{e.preventDefault();clarify(item)}}><label for={'item-project-'+item.id}>Dự án</label><select id={'item-project-'+item.id} bind:value={selectedProject}><option value="">Chọn dự án</option>{#each projects.filter(p=>p.status==='active') as project(project.id)}<option value={String(project.id)}>{project.name}</option>{/each}</select>{#if item.kind==='task'}<label for={'item-minutes-'+item.id}>Thời lượng dự kiến (phút, có thể để trống)</label><input id={'item-minutes-'+item.id} type="number" min="1" max="1440" bind:value={minutes}/><label for={'item-focus-'+item.id}>Mức tập trung</label><select id={'item-focus-'+item.id} bind:value={focus}><option value="">Chưa chọn</option><option value="low">Nhẹ</option><option value="medium">Vừa</option><option value="high">Cao</option></select>{/if}<div class="form-actions"><button type="button" class="secondary" onclick={()=>editing=null}>Hủy</button><button class="primary" disabled={clarifying||!projects.length}>{clarifying?'Đang lưu…':'Lưu phân loại'}</button></div>{#if !projects.length}<p class="muted">Tạo dự án trước khi phân loại.</p>{/if}</form>{/if}
 {/each}{/if}
</section>
